// Guides: one openable how-to per service, the same text next to its switch (Einstellungen → Funktionen),
// on its page in the "Ich" window and collected under Einbinden → Anleitungen. Services are sorted into
// fixed groups everywhere. Each guide: sw = admin switch id, me = page in the "Ich" window. Texts are [German, English]; every section is a list of such pairs.
// A self-test checks that every switch in Funktionen and every "Ich" page has a guide and a group.
const GGROUPS=[['talk','Gespräch','Conversation'],['data','Meine Daten','My data'],['day','Mein Tag','My day'],['post','Post und Kontakte','Mail and contacts'],
  ['home','Zuhause','Home'],['go','Unterwegs und Geräte','On the go and devices'],['sec','Zugang','Access']];
const GSECT=[['what','Was es kann','What it does'],['need','Was du brauchst','What you need'],['setup','Einrichten','Set up'],
  ['say','So benutzt du es','How to use it'],['out','Was das Haus verlässt','What leaves the house'],
  ['off','Ausschalten und löschen','Switch off and delete'],['fix','Wenn es nicht klappt','If it does not work']];
const NOTHING_OUT=[['Nichts. Alles bleibt auf dem Spark.','Nothing. Everything stays on the Spark.']];
const GUIDES=[
// ------------------------------------------------------------------ Gespräch
{id:'hands',grp:'talk',me:'setbox',t:['Freihändig und „Hey Spark“','Hands-free and "Hey Spark"'],
 what:[['Freihändig: Nach jeder Antwort hört der Assistent von selbst wieder zu, du musst nichts drücken. „Hey Spark“: Die Seite lauscht dauerhaft auf das Wort und startet dann das Gespräch.','Hands-free: after every answer the assistant listens again by itself, no tapping. "Hey Spark": the page keeps listening for the word and then starts the conversation.']],
 need:[['Eine Seite mit https (dein Reverse Proxy oder Port 31443), weil der Browser das Mikrofon sonst nicht freigibt.','A page over https (your reverse proxy or port 31443), otherwise the browser does not allow the microphone.'],['Ein angemeldetes Profil. Gäste haben beides nicht.','A signed-in profile. Guests get neither.']],
 setup:[['Im Assistenten unter dem Gesicht die Schalter „Freihändig“ und „Hey Spark“ antippen.','In the assistant, tap the "Hands-free" and "Hey Spark" switches below the face.'],['Feinheiten (Hineinreden, Gesprächspausen, Live-Text) stehen im Ich unter „Gespräch“.','Details (barge-in, pauses, live text) are under the Me → "Conversation".']],
 say:[['„Hey Spark, wie wird das Wetter morgen?“','"Hey Spark, what is the weather tomorrow?"'],['Während der Assistent spricht, einfach reinreden: Er hört auf und hört dir zu.','While the assistant speaks, just talk: it stops and listens.']],
 out:NOTHING_OUT,
 off:[['Schalter unter dem Gesicht wieder aus. Aufnahmen werden nie gespeichert.','Switch them off again below the face. Recordings are never stored.']],
 fix:[['Kein Mikrofon: Seite über https öffnen und dem Browser das Mikrofon erlauben.','No microphone: open the page over https and allow the microphone in the browser.'],['„Hey Spark“ reagiert nicht: Bildschirm muss an bleiben, auf dem Handy die Seite im Vordergrund lassen.','"Hey Spark" does not react: the screen has to stay on; on a phone keep the page in front.'],['Er fällt dir ins Wort: unter „Gespräch“ die Pause bis zur Antwort verlängern.','It cuts you off: make the pause before answering longer under "Conversation".']]},
{id:'search',grp:'talk',sw:'chat.search',t:['Websuche','Web search'],
 what:[['Braucht eine Frage aktuelle Informationen (Nachrichten, Öffnungszeiten, Preise), sucht der Assistent selbst im Netz und antwortet aus den Treffern.','When a question needs current information (news, opening hours, prices), the assistant searches the web itself and answers from the results.']],
 need:[['Deine eigene SearXNG-Instanz. Am besten mit JSON-Format (settings.yml: search.formats: [html, json]).','Your own SearXNG instance, ideally with the JSON format (settings.yml: search.formats: [html, json]).']],
 setup:[['Admin: Funktionen → Websuche, darunter die Adresse der SearXNG eintragen und speichern.','Admin: Features → Web search, enter the SearXNG address below it and save.'],['Admin: Einstellungen → Funktionen → Websuche einschalten.','Admin: Settings → Features → switch on Web search.']],
 say:[['„Was gibt es Neues zur Bahn-Streik?“','"Any news about the rail strike?"'],['„Wann hat der Baumarkt in Ulm heute offen?“','"When is the hardware store in Ulm open today?"']],
 out:[['Die Suchwörter gehen an deine SearXNG und von dort an die Suchmaschinen. Die Treffer-Seiten liest der Spark direkt.','The search words go to your SearXNG and from there to the search engines. The Spark reads the result pages directly.']],
 off:[['Schalter in Funktionen aus. Es wird nichts gespeichert außer der Antwort im Verlauf.','Switch it off under Features. Nothing is stored except the answer in the history.']],
 fix:[['„Keine Treffer“: In SearXNG das JSON-Format erlauben oder prüfen, ob der Spark die Adresse erreicht.','"No results": allow the JSON format in SearXNG or check that the Spark reaches the address.'],['Nach dem Lesen einer Mail ist die Websuche in derselben Antwort gesperrt. Das ist Absicht. Eine klare Suchfrage direkt danach („Wie hat Bayern gespielt?“) sucht wieder, ohne die Mail.','After reading a mail, web search is locked for that answer. That is on purpose. A clear search question right after it searches again, without the mail.'],['Sagt er, er könne nicht suchen: Log-Zeile „chat: web search“ zeigt den Grund (aus, keine Adresse, gesperrt).','If it says it cannot search: the log line "chat: web search" shows why (off, no address, locked).']]},
{id:'memory',grp:'data',sw:'chat.memory',me:'factbox',ng:1,t:['Gedächtnis','Memory'],
 what:[['Der Assistent merkt sich Dinge über dich, zum Beispiel Namen, Vorlieben oder wo etwas liegt, und nutzt sie in späteren Gesprächen. Nur für dein Profil.','The assistant remembers things about you, such as names, preferences or where something is, and uses them later. Only for your profile.']],
 need:[['Ein Profil (Name und PIN).','A profile (name and PIN).']],
 setup:[['Admin: Funktionen → Gedächtnis an.','Admin: Features → Memory on.'],['Profil: Ich → Gedächtnis zeigt alles, was gespeichert ist. Ob er auch selbst dazulernt, stellst du unter „Gespräch“ ein.','Profile: Me → Memory shows everything stored. Whether it also learns by itself is set under "Conversation".']],
 say:[['„Merk dir, der Ersatzschlüssel liegt in der Garage.“','"Remember, the spare key is in the garage."'],['„Vergiss das mit dem Schlüssel.“','"Forget the thing about the key."'],['„Was weißt du über mich?“','"What do you know about me?"']],
 out:NOTHING_OUT,
 off:[['Ich → Gedächtnis: einzelne Einträge löschen oder „Alles vergessen“.','Me → Memory: delete single entries or "Forget everything".']],
 fix:[['Doppelte Einträge: „Aufräumen vorschlagen“ fasst sie zusammen, geändert wird erst nach deinem OK.','Duplicate entries: "Suggest tidy-up" merges them, nothing changes before your OK.']]},
{id:'history',grp:'data',sw:'chat.history',ng:1,mep:'setbox',t:['Frühere Gespräche','Past conversations'],
 what:[['Du kannst nach früheren Gesprächen fragen. Aus ruhigen Gesprächen merkt sich der Assistent außerdem wenige dauerhafte Fakten (im Gedächtnis als „automatisch“ markiert).','You can ask about past conversations. From quiet conversations the assistant also keeps a few lasting facts (marked "automatic" in memory).']],
 need:[['Ein Profil. Gäste nie.','A profile. Never guests.']],
 setup:[['Admin: Funktionen → Frühere Gespräche an.','Admin: Features → Past conversations on.'],['Profil: Das automatische Lernen schaltest du unter Ich → Gespräch aus, wenn du es nicht willst.','Profile: switch automatic learning off under Me → Conversation if you do not want it.']],
 say:[['„Was hast du mir letzte Woche zum Grill gesagt?“','"What did you tell me about the grill last week?"'],['Im Verlauf: die Lupe durchsucht alle Gespräche.','In the history: the magnifier searches all conversations.']],
 out:NOTHING_OUT,
 off:[['Im Verlauf einzelne Nachrichten oder Gespräche löschen. Funktion aus: es wird nicht mehr gesucht.','Delete single messages or conversations in the history. Feature off: no more searching.']],
 fix:[['Findet nichts: genauer fragen, mit einem Stichwort aus dem damaligen Gespräch.','Finds nothing: ask more precisely, with a keyword from that conversation.']]},
{id:'style',grp:'talk',sw:'chat.own_style',ng:1,mep:'setbox',t:['Eigener Gesprächsstil','Own conversation style'],
 what:[['Jedes Profil sagt in eigenen Worten, wie der Assistent mit ihm reden soll: Anrede, Ton, Form, z. B. „Sprich mich mit Vornamen an und antworte locker.“','Each profile says in its own words how the assistant should talk to it: form of address, tone, form, e.g. "Call me by my first name and answer casually."']],
 need:[['Ein angemeldetes Profil. Gäste nie, eine fremde Stimme nie. Ändern nur im eigenen Browser, nicht über einen Geräteschlüssel.','A signed-in profile. Never guests, never another voice. Changed only in your own browser, not with a device key.']],
 setup:[['Admin: Funktionen → Eigener Gesprächsstil an.','Admin: Features → Own conversation style on.'],['Profil: Ich → Gespräch → Antwort → „So soll der Assistent mit mir reden“, höchstens 500 Zeichen.','Profile: Me → Conversation → Answer → "How the assistant should talk to me", at most 500 characters.']],
 say:[['Einfach wie immer fragen; der Ton folgt deinem Text.','Just ask as always; the tone follows your text.']],
 out:NOTHING_OUT,
 off:[['Text leeren oder Schalter aus.','Clear the text or switch it off.']],
 fix:[['Wirkt nicht: Der Text steht unter der Systemanweisung des Admins und über den festen Regeln. Werkzeugregeln, Codewort und Sperren kann er nicht ändern; Wünsche dazu bleiben ohne Wirkung. Der Admin sieht die Reihenfolge unter Einstellungen → Sprachmodell → „Ganzen Prompt ansehen“.','No effect: the text sits below the admin\'s system prompt and above the fixed rules. It cannot change tool rules, code word or locks; wishes about those have no effect. The admin sees the order under Settings → Language model → "Show the whole prompt".']]},
{id:'follow',grp:'talk',sw:'chat.follow_up',ng:1,mep:'setbox',t:['Rückfrage ohne Weckwort','Follow-up without wake word'],
 what:[['Nach der Antwort auf eine gesprochene Frage hört der Assistent noch ein paar Sekunden zu. So geht „Und morgen?“ oder „Mach es heller“ ohne erneutes „Hey Spark“. Sagst du nichts, ist das Mikrofon danach wieder aus. Anders als Freihändig hört er also nicht nach jeder Antwort bis zur Stille, sondern nur kurz und nur nach einer gesprochenen Frage.','After answering a spoken question the assistant keeps listening for a few seconds, so "And tomorrow?" or "Make it brighter" works without another "Hey Spark". If you say nothing, the microphone goes off again. Unlike hands-free it does not listen after every answer until silence, only briefly and only after a spoken question.']],
 need:[['Ein angemeldetes Profil und eine Seite mit https. Gäste nie, der Raum-Modus nie, getippte Fragen nie.','A signed-in profile and a page over https. Never guests, never room mode, never typed questions.']],
 setup:[['Admin: Funktionen → Rückfrage ohne Weckwort an.','Admin: Features → Follow-up without wake word on.'],['Profil: Ich → Gespräch → „Rückfrage ohne Weckwort“ auf 4 bis 10 Sekunden.','Profile: Me → Conversation → "Follow-up without wake word" to 4 to 10 seconds.']],
 say:[['„Hey Spark, wie wird das Wetter morgen?“ … „Und am Wochenende?“','"Hey Spark, what is the weather tomorrow?" … "And at the weekend?"']],
 out:NOTHING_OUT,
 off:[['Im Profil auf „aus“ stellen oder der Admin schaltet es für alle aus. Aufnahmen werden nie gespeichert.','Set it to "off" in the profile, or the admin switches it off for everybody. Recordings are never stored.']],
 fix:[['Er nimmt Fernseher oder Gespräche als Frage: kürzere Dauer wählen oder ausschalten.','It takes the TV or talk in the room as a question: pick a shorter time or switch it off.']]},
{id:'selfecho',grp:'talk',sw:'chat.no_self_echo',ng:1,mep:'setbox',t:['Eigene Stimme überhören','Ignore my own voice'],
 what:[['Jedes Gerät filtert nur sein eigenes Echo. Antwortet der Lautsprecher und das iPhone daneben hört zu, hörte es bisher die Spark-Stimme als neue Frage. Jetzt merkt sich der Spark 60 Sekunden lang, was er gesagt hat, und überhört eine Aufnahme, die aus diesen Sätzen besteht. Auf Wunsch überhört er außerdem alles, was ein anderes Gerät desselben Profils aufnimmt, während ein Gerät gerade spricht.','Every device only filters its own echo. When the speaker answers and the iPhone next to it listens, it used to hear the Spark voice as a new question. Now the Spark remembers for 60 seconds what it said and ignores a recording made of those sentences. Optionally it also ignores everything another device of the same profile records while one device is speaking.']],
 need:[['Ein angemeldetes Profil (Anmeldung, iPhone-App oder Lautsprecher). Gäste nie: sonst könnte ein Gast ausprobieren, was der Spark gerade jemand anderem gesagt hat.','A signed-in profile (login, iPhone app or speaker). Never guests: a guest could otherwise test what the Spark just said to someone else.']],
 setup:[['Admin: Funktionen → Eigene Stimme überhören an, darunter „Was er überhört“ wählen.','Admin: Features → Ignore my own voice on, then pick "What it ignores" below.'],['Profil: Ich → Gespräch → „Eigene Stimme überhören“ ist dann an und lässt sich ausschalten.','Profile: Me → Conversation → "Ignore my own voice" is then on and can be switched off.']],
 say:[['Nichts Besonderes. „Spark, …“ oder „Jarvis, …“ am Satzanfang zählt immer. „Ja“, „Stopp“ und andere kurze Sätze unter drei Wörtern werden nie überhört.','Nothing special. "Spark, …" or "Jarvis, …" at the start always counts. "Ja", "Stopp" and other short sentences under three words are never ignored.']],
 out:NOTHING_OUT,
 off:[['Im Profil ausschalten oder der Admin schaltet es für alle aus. Was der Spark gesagt hat, liegt nur 60 Sekunden im Arbeitsspeicher, nie auf der Platte und nie im Log.','Switch it off in the profile, or the admin switches it off for everybody. What the Spark said stays in memory for 60 seconds only, never on disk and never in the log.']],
 fix:[['Eine echte Frage wird überhört, während ein anderes Gerät spricht: „Was er überhört“ auf „Sätze, die er gerade selbst gesagt hat“ stellen. Im Log steht dann „chat: ignored (speaking pause)“ bzw. „(own voice)“, nie der Text.','A real question is ignored while another device speaks: set "What it ignores" to "Sentences it just said itself". The log then shows "chat: ignored (speaking pause)" or "(own voice)", never the text.']]},
{id:'fixes',grp:'talk',sw:'chat.learn_fixes',ng:1,mep:'setbox',t:['Aus Korrekturen lernen','Learning from corrections'],
 what:[['Korrigierst du den Assistenten („Nein, mein Bruder heißt Tim“, „Du sollst bei Terminen immer nachsehen“), macht er daraus einen kurzen Satz und fragt: „Soll ich mir merken …?“ Gespeichert wird erst nach deinem „Ja“, in deinem Gedächtnis.','If you correct the assistant ("No, my brother is called Tim", "You should always check the calendar for appointments"), it turns this into a short sentence and asks: "Shall I remember …?" It is stored only after your "yes", in your memory.'],['Die Frage, bei der er falsch lag, kannst du im Protokoll als Testfall an den Admin geben: Der Qualitätstest prüft sie dann nach jedem Update.','You can hand the question it got wrong to the admin as a test case from the log: the quality test then checks it after every update.']],
 need:[['Ein Profil mit Gedächtnis. Gäste nie, eine fremde Stimme nie.','A profile with memory. Never guests, never another voice.']],
 setup:[['Admin: Funktionen → Aus Korrekturen lernen an.','Admin: Features → Learning from corrections on.'],['Profil: Ich → Gespräch → „Aus Korrekturen lernen“ an.','Profile: Me → Conversation → "Learn from corrections" on.']],
 say:[['„Nein, das stimmt nicht, mein Bruder heißt Tim.“ Dann auf die Frage mit „Ja“ antworten.','"No, that is wrong, my brother is called Tim." Then answer the question with "yes".']],
 out:NOTHING_OUT,
 off:[['Schalter aus. Gemerkte Sätze löschst du unter Ich → Gedächtnis, Testfälle der Admin unter Zustand → Prüfen → Qualitätstest.','Switch off. Delete remembered sentences under Me → Memory; the admin deletes test cases under Status → Checks → Quality test.']],
 fix:[['Nichts zum Merken: Weltwissen (Ergebnisse, Preise), Codewörter, PINs, Sicherheitsregeln und das Schalten von Geräten lernt er nie. Aus Mails oder Webseiten lernt er auch nicht.','Nothing to remember: it never learns world knowledge (scores, prices), code words, PINs, security rules or switching devices. It does not learn from mail or web pages either.']]},
{id:'toolthink',grp:'talk',sw:'chat.tool_thinking',ng:1,mep:'setbox',t:['Bei der Werkzeugwahl nachdenken','Thinking while choosing tools'],
 what:[['Das Modell denkt kurz nach, bevor es ein Werkzeug wählt (Kalender, Mail, Websuche …). Das macht die Wahl zuverlässiger; danach antwortet es ohne Nachdenken.','The model thinks briefly before it picks a tool (calendar, mail, web search …). That makes the choice more reliable; afterwards it answers without thinking.']],
 need:[['Ein Profil. Gäste nie.','A profile. Never guests.']],
 setup:[['Admin: Funktionen → Bei der Werkzeugwahl nachdenken an.','Admin: Features → Thinking while choosing tools on.'],['Profil: Ich → Gespräch → „Bei Werkzeugen nachdenken“ an.','Profile: Me → Conversation → "Think before tools" on.']],
 say:[['Nichts Besonderes, einfach fragen.','Nothing special, just ask.']],
 out:NOTHING_OUT,
 off:[['Schalter aus, hier oder im eigenen Profil.','Switch off, here or in your own profile.']],
 fix:[['Antworten beginnen spürbar später: Das ist der Preis fürs Nachdenken; dann wieder ausschalten.','Answers start noticeably later: that is the price of thinking; switch it off again then.']]},
{id:'speaker',grp:'sec',sw:'chat.speaker_id',me:'voicebox',ng:1,t:['Sprechererkennung','Speaker recognition'],
 what:[['Der Assistent erkennt dich an der Stimme, auch an einem fremden Gerät, und antwortet dann mit deinem Gedächtnis und deinen Einstellungen. Smart Home schaltet er für eine fremde Stimme nie.','The assistant recognises you by voice, even on someone else\'s device, and then answers with your memory and settings. It never switches smart home for a foreign voice.']],
 need:[['Ein Profil und ein Mikrofon (https).','A profile and a microphone (https).']],
 setup:[['Admin: Funktionen → Sprechererkennung an, darunter die Strenge wählen.','Admin: Features → Speaker recognition on, choose the strictness below it.'],['Profil: Ich → Sprechererkennung → „Stimme einlernen“, drei kurze Sätze vorlesen.','Profile: Me → Speaker identification → "Enroll voice", read three short sentences.']],
 say:[['Einfach sprechen. Wird eine andere Stimme erkannt, steht ihr Name an der Antwort.','Just talk. If another voice is recognised, its name is shown on the answer.']],
 out:NOTHING_OUT,
 off:[['Ich → Sprechererkennung → „Stimme löschen“.','Me → Speaker identification → "Delete voice".']],
 fix:[['Eine Stimme ist kein Passwort: Wer sehr ähnlich klingt oder eine Aufnahme abspielt, kann ein Profil erwischen.','A voice is not a password: someone who sounds very similar or plays a recording can get a profile.'],['Wird selten erkannt: in ruhiger Umgebung neu einlernen oder die Strenge auf „locker“.','Rarely recognised: enroll again somewhere quiet or set strictness to "relaxed".']]},
{id:'room',grp:'home',sw:'chat.room',me:'roombox',ng:1,t:['Raum-Modus','Room mode'],
 what:[['Für eine gewählte Zeit hört der Assistent dem Gespräch im Raum zu und hilft in einer Pause: offene Fragen beantworten, Termine oder Einkäufe vorschlagen, bei „kalt“ oder „dunkel“ den echten Wert nennen. Geändert wird nur nach „Ja“.','For a chosen time the assistant listens to the conversation in the room and helps in a pause: answers open questions, suggests appointments or shopping items, gives the real value on "cold" or "dark". Nothing changes without "Yes".']],
 need:[['Ein Profil und ein Gerät mit Mikrofon. Alle im Raum sollten wissen, dass er zuhört.','A profile and a device with a microphone. Everyone in the room should know it is listening.']],
 setup:[['Admin: Funktionen → Raum-Modus an.','Admin: Features → Room mode on.'],['Profil: Ich → Raum-Modus: was er tun darf, Raum in Home Assistant, „Nur als Text“.','Profile: Me → Room mode: what it may do, room in Home Assistant, "Text only".'],['Am Gerät: Schalter „Raum“ unter dem Gesicht, Dauer wählen.','On the device: "Room" switch below the face, choose the duration.'],['Eigene Lautsprecher (ESP32): Ich → Lautsprecher → Lautsprecher antippen → Raum-Modus „Starten“ (dort auch Dauer und was er anbieten darf), oder am Lautsprecher „Raummodus an“ / „Raummodus aus“.','Own speakers (ESP32): Me → Speakers → tap the speaker → room mode "Start" (duration and what it may offer are there too), or at the speaker "Raummodus an" / "Raummodus aus".']],
 say:[['Ihr redet ganz normal. „Ja“ übernimmt einen Vorschlag, „Nein“ verwirft ihn.','Talk normally. "Yes" takes a suggestion, "No" drops it.']],
 out:NOTHING_OUT,
 off:[['Schalter „Raum“ aus. Das Gehörte bleibt nur wenige Minuten im Arbeitsspeicher und wird nie gespeichert.','"Room" switch off. What was heard stays in memory for a few minutes only and is never stored.']],
 fix:[['Meldet sich zu oft: unter Raum-Modus die Stufe auf „nur Fragen“.','Speaks up too often: set the level to "questions only" under Room mode.']]},
{id:'roomtv',grp:'home',sw:'chat.room_voices',me:'roombox',ng:1,t:['Fernsehstimmen überhören','Ignore TV voices'],
 what:[['Im Raum-Modus zählen nur Stimmen, die der Spark kennt: Fernseher, Radio und Besuch lösen keine Fragen und Vorschläge aus. Auf Wunsch nur, solange Home Assistant einen eingeschalteten Fernseher im Raum meldet. Fremde Sätze vergisst er sofort.','In room mode only voices the Spark knows count: TV, radio and visitors trigger no questions or suggestions. Optionally only while Home Assistant reports a TV on in the room. Foreign sentences are forgotten at once.']],
 need:[['Raum-Modus und Sprechererkennung an, die Stimmen angelernt unter Ich → Sprechererkennung. Für „wenn der Fernseher läuft“: Home Assistant mit dem Fernseher als Mediaplayer im Raum des Geräts.','Room mode and speaker identification on, voices taught under Me → Speaker identification. For "while the TV is on": Home Assistant with the TV as a media player in the device\'s room.']],
 setup:[['Admin: Funktionen → Raum-Modus → Fernsehstimmen überhören an.','Admin: Features → Room mode → Ignore TV voices on.'],['Pro Gerät: Ich → Raum-Modus → „Wem er zuhört“ (Lautsprecher: Ich → Lautsprecher). Erst mit „Probelauf“: Am Ende steht da, wie viele Sätze er überhört hätte.','Per device: Me → Room mode → "Who it listens to" (speakers: Me → Speakers). Start with "Trial": at the end it says how many sentences it would have ignored.']],
 say:[['„Spark, …“ am Satzanfang zählt immer, auch von Besuch. „Stopp“ und „Raummodus aus“ gelten von jeder Stimme.','"Spark, …" at the start always counts, also from visitors. "Stopp" and "Raummodus aus" work from any voice.']],
 out:NOTHING_OUT,
 off:[['„Wem er zuhört: allen“, oder der Admin-Schalter aus.','"Who it listens to: everybody", or the admin switch off.']],
 fix:[['Überhört dich selbst: Stimme unter Ich → Sprechererkennung mit mehr Aufnahmen aus der Sofa-Entfernung anlernen, oder die Strenge der Sprechererkennung (Funktionen) auf „locker“. Sehr kurze Sätze erkennt die Sprechererkennung oft nicht.','Ignores you: teach your voice under Me → Speaker identification with more recordings from sofa distance, or set the speaker identification strictness (Features) to "relaxed". Very short sentences are often not recognized.']]},
{id:'proactive',grp:'day',sw:'chat.proactive',me:'probox',ng:1,t:['Von selbst melden','Speaking up by itself'],
 what:[['Der Assistent meldet sich, wenn wirklich etwas ist: vor Terminen, bei eigenen Smart-Home-Regeln, Mails von gewählten Absendern, Wetter für morgen, Geburtstagen, Paketen, mit einer Nachfrage oder einer Begrüßung.','The assistant speaks up when something is really up: before appointments, on your own smart-home rules, mails from chosen senders, tomorrow\'s weather, birthdays, parcels, a follow-up or a greeting.']],
 need:[['Ein Profil. Für Mitteilungen ohne offene Seite: Mitteilungen eingeschaltet (siehe „Mitteilungen aufs Handy“).','A profile. For notices without an open page: notifications switched on (see "Notifications to your phone").']],
 setup:[['Admin: Funktionen → Von selbst melden an.','Admin: Features → Speaking up by itself on.'],['Profil: Ich → Von selbst: jede Art einzeln an, Ruhezeit (Standard 22 bis 7 Uhr) und Tageslimit setzen, „Ausprobieren“.','Profile: Me → Proactive: switch on each kind, set quiet hours (default 10 pm to 7 am) and daily limit, "Try it".']],
 say:[['Auf eine Meldung: „Ja“, „Nicht jetzt“ oder „Interessiert mich nicht“, oder die drei Knöpfe darunter.','On a notice: "Yes", "Not now" or "Not interested", or the three buttons below it.']],
 out:[['Für den Wetterhinweis geht eine Suche an deine SearXNG. Sonst nichts.','For the weather hint a search goes to your SearXNG. Nothing else.']],
 off:[['Ich → Von selbst: einzelne Arten oder alles aus.','Me → Proactive: single kinds or everything off.']],
 fix:[['Kommt nichts: Ruhezeit und Tageslimit prüfen, „Ausprobieren“ drücken.','Nothing arrives: check quiet hours and daily limit, press "Try it".']]},
// ------------------------------------------------------------------ Mein Tag
{id:'reminders',grp:'day',sw:'chat.reminders',t:['Timer und Erinnerungen','Timers and reminders'],
 what:[['Timer und Erinnerungen per Sprache. Das Gerät klingelt und sagt es an.','Timers and reminders by voice. The device rings and says it.']],
 need:[['Nichts. Profile speichern sie auf dem Spark, Gäste nur im Browser. Ohne offene Seite: Mitteilungen einschalten.','Nothing. Profiles keep them on the Spark, guests only in the browser. Without an open page: switch on notifications.']],
 setup:[['Admin: Funktionen → Timer und Erinnerungen an.','Admin: Features → Timers and reminders on.']],
 say:[['„Erinnere mich in 10 Minuten an den Ofen.“','"Remind me about the oven in 10 minutes."'],['„Erinnere mich morgen um 8 an den Müll.“','"Remind me about the bins tomorrow at 8."'],['„Welche Erinnerungen habe ich?“','"Which reminders do I have?"']],
 out:NOTHING_OUT,
 off:[['Im Assistenten unter der Erinnerungsliste löschen.','Delete them in the reminder list in the assistant.']],
 fix:[['Klingelt nicht: Seite offen lassen oder Mitteilungen einschalten.','Does not ring: keep the page open or switch on notifications.']]},
{id:'tasks',grp:'day',sw:'chat.tasks',me:'taskbox',ng:1,t:['Aufgaben und Einkaufsliste','Tasks and shopping list'],
 what:[['Zwei Listen, Einkaufsliste und Aufgaben. Du setzt per Sprache Einträge drauf, fragst, was draufsteht, und hakst ab. Offene Aufgaben kommen ins Tagesbriefing.','Two lists, shopping list and tasks. You add entries by voice, ask what is on them and tick them off. Open tasks go into the daily briefing.']],
 need:[['Weg A (iPhone): nichts außer einem Kurzbefehl, der neue Einträge in die Erinnerungen-App holt. Apples Erinnerungen sind über CalDAV nicht mehr erreichbar, deshalb dieser Umweg.','Way A (iPhone): only a shortcut that fetches new entries into the Reminders app. Apple\'s Reminders cannot be reached over CalDAV any more, hence this detour.'],['Weg B: ein CalDAV-Konto mit Aufgabenlisten (Nextcloud, mailbox.org, Radicale), unter Kalender verbunden.','Way B: a CalDAV account with task lists (Nextcloud, mailbox.org, Radicale), connected under Calendar.']],
 setup:[['Admin: Funktionen → Aufgaben und Einkaufsliste an.','Admin: Features → Tasks and shopping list on.'],['Profil: Ich → Aufgaben → „Listen für mich nutzen“ an.','Profile: Me → Tasks → switch on "Use lists for me".'],['Weg A: Gerät „iPhone Listen“ anlegen, dann den Kurzbefehl wie unten auf der Seite beschrieben bauen und als Automation laufen lassen.','Way A: add a device "iPhone lists", then build the shortcut as described at the bottom of the page and run it as an automation.'],['Weg B: „CalDAV-Listen suchen“ und die Aufgabenliste auswählen.','Way B: "Find CalDAV lists" and pick the task list.']],
 say:[['„Setz Milch und Brot auf die Einkaufsliste.“','"Put milk and bread on the shopping list."'],['„Was steht auf meiner Aufgabenliste?“','"What is on my to-do list?"'],['„Hak die Milch ab.“ Dann „Ja“.','"Tick off the milk." Then "Yes".']],
 out:[['Weg A: nichts, das iPhone holt die Einträge selbst ab. Weg B: der Spark spricht direkt mit deinem CalDAV-Server.','Way A: nothing, the iPhone fetches the entries itself. Way B: the Spark talks directly to your CalDAV server.']],
 off:[['Ich → Aufgaben → Schalter aus. Die Einträge auf dem Spark bleiben, bis du sie abhakst.','Me → Tasks → switch off. The entries on the Spark stay until you tick them off.']],
 fix:[['Kurzbefehl holt nichts: Schlüssel im Header X-Speech-Device prüfen; schon übergebene Einträge kommen nicht noch einmal.','Shortcut fetches nothing: check the key in the X-Speech-Device header; entries already handed over do not come again.'],['Keine CalDAV-Liste gefunden: Nextcloud-Aufgaben brauchen die App „Tasks“; iCloud bietet keine.','No CalDAV list found: Nextcloud tasks need the "Tasks" app; iCloud offers none.']]},
{id:'calendar',grp:'day',sw:'chat.calendar',me:'calbox',ng:1,t:['Kalender','Calendar'],
 what:[['Der Assistent liest deine Termine vor und trägt neue ein, aber erst nach deinem „Ja“.','The assistant reads your appointments and adds new ones, but only after your "Yes".']],
 need:[['iCloud: Apple-ID und ein app-spezifisches Passwort von appleid.apple.com. Nextcloud oder anderer CalDAV-Server: Adresse und App-Passwort. Oder ein Abo-Link (webcal), dann nur lesen.','iCloud: Apple ID and an app-specific password from appleid.apple.com. Nextcloud or another CalDAV server: address and app password. Or a subscription link (webcal), then read only.']],
 setup:[['Admin: Funktionen → Kalender und Tagesbriefing an.','Admin: Features → Calendar and daily briefing on.'],['Profil: Ich → Kalender → „Kalender hinzufügen“, Anbieter wählen, Zugangsdaten eintragen, „Prüfen und hinzufügen“.','Profile: Me → Calendar → "Add calendar", pick the provider, enter the login, "Check and add".']],
 say:[['„Was steht heute an?“','"What is on today?"'],['„Hab ich am Freitag Zeit?“','"Am I free on Friday?"'],['„Trag Zahnarzt Dienstag 10 Uhr ein.“ Dann „Ja“.','"Add dentist Tuesday 10 am." Then "Yes".']],
 out:[['Der Spark spricht direkt mit deinem Kalenderdienst (z. B. iCloud). Sonst geht nichts raus.','The Spark talks directly to your calendar service (e.g. iCloud). Nothing else leaves.']],
 off:[['Ich → Kalender → „Entfernen“. Das Passwort wird dabei gelöscht.','Me → Calendar → "Remove". The password is deleted with it.']],
 fix:[['iCloud lehnt ab: neues app-spezifisches Passwort erzeugen, nicht das Apple-ID-Passwort.','iCloud refuses: create a new app-specific password, not the Apple ID password.'],['„Nächste Termine zeigen“ prüft die Verbindung.','"Show next appointments" checks the connection.']]},
{id:'briefing',grp:'day',me:'calbox',t:['Morgen-Briefing','Morning briefing'],
 what:[['Auf „Guten Morgen“ oder zu einer festen Uhrzeit: Termine, Erinnerungen, Wetter, Geburtstage, Pakete, ungelesene Mails und bis zu drei Themen, kurz zusammengefasst (was davon eingeschaltet ist).','On "Good morning" or at a set time: appointments, reminders, weather, birthdays, parcels, unread mail and up to three topics, briefly (whatever is switched on).']],
 need:[['Einen verbundenen Kalender. Für die feste Uhrzeit: Mitteilungen.','A connected calendar. For the set time: notifications.']],
 setup:[['Profil: Ich → Kalender → Themen eintragen (z. B. „Wetter Ulm, Nachrichten“).','Profile: Me → Calendar → enter topics (e.g. "weather Ulm, news").'],['Profil: Ich → Mitteilungen → Uhrzeit fürs Tagesbriefing.','Profile: Me → Notifications → time for the daily briefing.']],
 say:[['„Guten Morgen.“','"Good morning."'],['„Was steht heute an?“','"What is on today?"']],
 out:[['Für die Themen geht eine Suche an deine SearXNG.','For the topics a search goes to your SearXNG.']],
 off:[['Uhrzeit auf „Aus“, Themen leeren.','Set the time to "Off", clear the topics.']],
 fix:[['Kommt morgens nicht: Mitteilungen auf diesem Gerät eingeschaltet?','Does not arrive in the morning: are notifications on for this device?']]},
{id:'weather',grp:'day',sw:'chat.weather',me:'wxbox',ng:1,t:['Wetter','Weather'],
 what:[['Die Vorhersage für deinen Ort: jetzt, heute, morgen und bis zu 7 Tage, mit Regen in den nächsten Stunden. Der Spark macht aus den Zahlen feste Sätze, das Modell liest sie nur vor.','The forecast for your place: now, today, tomorrow and up to 7 days, with rain in the next hours. The Spark turns the numbers into fixed sentences, the model only reads them.']],
 need:[['Nichts außer deinem Ort. Open-Meteo braucht keinen Schlüssel.','Nothing but your place. Open-Meteo needs no key.']],
 setup:[['Admin: Funktionen → Wetter an. Eigene Open-Meteo-Adresse (falls selbst betrieben) direkt darunter.','Admin: Features → Weather on. Own Open-Meteo address (if self-hosted) right below it.'],['Profil: Ich → Wetter → „Wetter für mich nutzen“ an, Ort eintragen, „Speichern“.','Profile: Me → Weather → switch on "Use weather for me", enter your place, "Save".']],
 say:[['„Wie wird das Wetter morgen?“','"What is the weather tomorrow?"'],['„Regnet es heute noch?“','"Will it rain today?"'],['„Wie wird das Wetter am Wochenende in Hamburg?“','"What is the weather at the weekend in Hamburg?"']],
 out:[['Die Koordinaten deines Orts gehen an Open-Meteo, bei einem anderen Ort dessen Name an die Ortssuche.','The coordinates of your place go to Open-Meteo; for another place its name goes to the place search.']],
 off:[['Ich → Wetter → Schalter aus, Ort leeren und speichern.','Me → Weather → switch off, clear the place and save.']],
 fix:[['Ort nicht gefunden: den nächsten größeren Ort oder „Ort, Land“ eintragen.','Place not found: enter the nearest larger town or "town, country".'],['„Nicht erreichbar“: Der Spark braucht Internet zu api.open-meteo.com.','"Not reachable": the Spark needs internet access to api.open-meteo.com.']]},
{id:'transit',grp:'go',sw:'chat.transit',me:'trbox',ng:1,t:['Bus und Bahn','Bus and train'],
 what:[['Die nächsten Abfahrten an deiner Haltestelle und Verbindungen zu einem Ziel, mit Verspätungen und Gleis. Mit einer Pendelstrecke meldet „Von selbst“, wenn dein Zug später kommt oder ausfällt.','The next departures at your stop and connections to a destination, with delays and platform. With a commute set, "Proactive" tells you when your train is late or cancelled.']],
 need:[['Nichts weiter. Der Fahrplan kommt von transport.rest (Deutsche Bahn mit Bus und Tram); der Admin kann einen anderen Dienst eintragen.','Nothing else. The timetable comes from transport.rest (Deutsche Bahn including bus and tram); the admin can enter another service.']],
 setup:[['Admin: Funktionen → Bus und Bahn an.','Admin: Features → Bus and train on.'],['Profil: Ich → Bus und Bahn → Schalter an, Haltestelle suchen und antippen.','Profile: Me → Bus and train → switch on, search your stop and tap it.'],['Für Verspätungshinweise: Ziel und Abfahrtszeit eintragen, Tage wählen, Ziel suchen und antippen; dann unter „Von selbst“ „Bus und Bahn“ einschalten.','For delay notes: enter destination and departure time, pick the days, search the destination and tap it; then switch on "Bus and train" under "Proactive".']],
 say:[['„Wann fährt der nächste Bus?“','"When does the next bus leave?"'],['„Wie komme ich um 8 nach Karlsruhe?“','"How do I get to Karlsruhe at 8?"']],
 out:[['Die Namen deiner Haltestelle und deines Ziels gehen an den Fahrplandienst.','The names of your stop and destination go to the timetable service.']],
 off:[['Ich → Bus und Bahn → Schalter aus, Pendelstrecke löschen.','Me → Bus and train → switch off, remove the commute.']],
 fix:[['„Nicht erreichbar“: Der öffentliche Dienst ist manchmal überlastet. Der Admin kann eine andere Adresse eintragen, z. B. einen eigenen db-rest.','"Not reachable": the public service is sometimes overloaded. The admin can enter another address, e.g. an own db-rest.'],['Falsche Haltestelle: genauer suchen, z. B. mit Ort („Karlsbad Langensteinbach Bahnhof“).','Wrong stop: search more precisely, e.g. with the town.']]},
{id:'contacts',grp:'post',sw:'chat.contacts',me:'conbox',ng:1,ro:1,t:['Kontakte','Contacts'],
 what:[['Der Assistent kennt Telefonnummern, E-Mail-Adressen und Geburtstage aus deinem Adressbuch. Geburtstage kommen ins Tagesbriefing, Mails zeigen Namen statt Adressen. Er liest nur.','The assistant knows phone numbers, e-mail addresses and birthdays from your address book. Birthdays go into the daily briefing, mails show names instead of addresses. It only reads.']],
 need:[['iCloud: Apple-ID und ein app-spezifisches Passwort von appleid.apple.com. Nextcloud oder anderer CardDAV-Server: Adresse und App-Passwort.','iCloud: Apple ID and an app-specific password from appleid.apple.com. Nextcloud or another CardDAV server: address and app password.']],
 setup:[['Admin: Funktionen → Kontakte an.','Admin: Features → Contacts on.'],['Profil: Ich → Kontakte → „Kontakte für mich nutzen“ an.','Profile: Me → Contacts → switch on "Use contacts for me".'],['„Adressbuch hinzufügen“: Anbieter wählen, Zugangsdaten, „Prüfen und hinzufügen“.','"Add address book": pick the provider, enter the login, "Check and add".']],
 say:[['„Wie ist die Nummer von Anna?“','"What is Anna\'s number?"'],['„Wann hat Bert Geburtstag?“','"When is Bert\'s birthday?"']],
 out:[['Der Spark spricht direkt mit deinem Adressbuch-Dienst. Die Kontakte liegen verschlüsselt auf dem Spark.','The Spark talks directly to your address book service. The contacts are kept encrypted on the Spark.']],
 off:[['Ich → Kontakte → „Entfernen“ löscht Zugang und gespeicherte Kontakte.','Me → Contacts → "Remove" deletes the login and the stored contacts.']],
 fix:[['iCloud lehnt ab: neues app-spezifisches Passwort erzeugen.','iCloud refuses: create a new app-specific password.'],['Neue Kontakte fehlen: „Jetzt abholen“ (sonst einmal am Tag).','New contacts missing: "Fetch now" (otherwise once a day).']]},
// ------------------------------------------------------------------ Post und Dokumente
{id:'wyoming',grp:'home',sw:'chat.wyoming',t:['Home Assistant Assist (Wyoming)','Home Assistant Assist (Wyoming)'],
 what:[['Home Assistant nutzt die Spracherkennung und die Stimme des Spark. Damit verstehen Voice PE, die HA-App und ESPHome-Lautsprecher dich lokal, und HA antwortet in der Spark-Stimme. Die Befehle führt Home Assistant selbst aus.','Home Assistant uses the Spark\'s speech recognition and voice. Voice PE, the HA app and ESPHome speakers understand you locally, and HA answers in the Spark voice. Home Assistant carries out the commands itself.']],
 need:[['Home Assistant im selben Netz und dessen IP-Adresse. Die volle Installation mit Panel (der Dienst läuft im Panel).','Home Assistant on the same network and its IP address. The full install with the panel (the service runs inside the panel).']],
 setup:[['Admin: Funktionen → Home Assistant Assist an, die Adresse von Home Assistant bei „Erlaubte Adressen“ eintragen, Speichern.','Admin: Features → Home Assistant Assist on, enter Home Assistant\'s address under "Allowed addresses", save.'],['In Home Assistant: Einstellungen → Geräte & Dienste → Integration hinzufügen → „Wyoming Protocol“. Host: die Adresse des Spark, Port: 31003.','In Home Assistant: Settings → Devices & services → Add integration → "Wyoming Protocol". Host: the Spark\'s address, port: 31003.'],['Einstellungen → Sprachassistenten → deinen Assistenten öffnen: bei Sprache-zu-Text und Text-zu-Sprache „spark“ wählen, Sprache Deutsch.','Settings → Voice assistants → open your assistant: pick "spark" for speech-to-text and text-to-speech, language German.']],
 say:[['Wie gewohnt mit deinem HA-Sprachgerät, z. B. „Mach das Licht im Wohnzimmer an“.','As usual with your HA voice device, e.g. "Turn on the living room light".']],
 out:[['Nichts verlässt das Haus. Home Assistant schickt Ton an den Spark und bekommt Text oder Ton zurück.','Nothing leaves the house. Home Assistant sends audio to the Spark and gets text or audio back.']],
 off:[['Funktionen → Home Assistant Assist aus. In HA die Wyoming-Integration löschen.','Features → Home Assistant Assist off. Delete the Wyoming integration in HA.']],
 fix:[['HA findet nichts: Stimmt die erlaubte Adresse? Im Log steht „wyoming: refused“ mit der Adresse, die anklopft; genau die eintragen.','HA finds nothing: is the allowed address right? The log shows "wyoming: refused" with the address knocking; enter exactly that one.'],['Langsam: Läuft gleichzeitig ein großes Sprachmodell, braucht die Stimme länger.','Slow: while a large language model is running, the voice takes longer.']]},
{id:'mail',grp:'post',sw:'chat.mail',me:'mailbox',ng:1,ro:1,t:['E-Mail lesen','Reading e-mail'],
 what:[['Der Assistent liest deinen Posteingang der letzten 30 Tage vor. Er sendet, löscht und markiert nichts.','The assistant reads your inbox of the last 30 days. It sends, deletes and marks nothing.']],
 need:[['Bis zu 4 Postfächer: iCloud, Gmail, GMX, web.de oder IMAP. Bei iCloud und Gmail ein app-spezifisches Passwort.','Up to 4 mailboxes: iCloud, Gmail, GMX, web.de or IMAP. For iCloud and Gmail an app-specific password.']],
 setup:[['Admin: Funktionen → E-Mail lesen an.','Admin: Features → Reading e-mail on.'],['Profil: Ich → E-Mail → „Postfach hinzufügen“, „Prüfen und hinzufügen“.','Profile: Me → E-mail → "Add mailbox", "Check and add".']],
 say:[['„Hab ich neue Mails?“','"Do I have new mail?"'],['„Was schreibt Anna?“','"What does Anna write?"'],['„Lies mir die Mail von der Telekom vor.“','"Read me the mail from Telekom."']],
 out:[['Der Spark spricht direkt mit deinem Mailserver. Sonst nichts.','The Spark talks directly to your mail server. Nothing else.']],
 off:[['Ich → E-Mail → Postfach entfernen. Das Passwort wird gelöscht.','Me → E-mail → remove the mailbox. The password is deleted.']],
 fix:[['Anmeldung scheitert: app-spezifisches Passwort nehmen, bei Gmail IMAP in den Gmail-Einstellungen erlauben.','Login fails: use an app-specific password; for Gmail allow IMAP in the Gmail settings.'],['Nach dem Lesen einer Mail sind Smart Home und Websuche in derselben Antwort gesperrt. Das schützt vor Mails, die etwas auslösen wollen.','After reading a mail, smart home and web search are locked for that answer. That protects against mails trying to trigger something.']]},
{id:'tidy',grp:'post',sw:'chat.mail_tidy',me:'mailbox',ng:1,t:['Postfach aufräumen','Inbox tidying'],
 what:[['Werbung, Newsletter und Ähnliches kommen in eigene Ordner (Hauptordner frei wählbar, sonst „Spark“). Es wird nie gelöscht und nie gesendet. Auf Wunsch legt er Antwort-Entwürfe an.','Advertising, newsletters and the like go into their own folders (main folder of your choice, else "Spark"). Nothing is ever deleted or sent. On request it writes reply drafts.']],
 need:[['Ein verbundenes Postfach (siehe „E-Mail lesen“).','A connected mailbox (see "Reading e-mail").']],
 setup:[['Admin: Funktionen → E-Mail lesen und Postfach aufräumen an.','Admin: Features → Reading e-mail and Inbox tidying on.'],['Profil: Ich → E-Mail → Aufräumen: pro Postfach Modus wählen. Erst eine Woche „Vorschau“, dann „sicher“ oder „automatisch“.','Profile: Me → E-mail → Tidying: pick a mode per mailbox. First a week of "preview", then "safe" or "automatic".']],
 say:[['„Räum mein Postfach auf.“','"Tidy my inbox."'],['„Schreib Anna eine Antwort, dass ich komme.“ Dann „Ja“: der Entwurf landet in Entwürfe.','"Write Anna a reply that I am coming." Then "Yes": the draft goes into Drafts.']],
 out:[['Nichts außer den Befehlen an deinen eigenen Mailserver.','Nothing except the commands to your own mail server.']],
 off:[['Modus auf „aus“. Jede Verschiebung lässt sich 30 Tage lang zurückholen.','Mode "off". Every move can be undone for 30 days.']],
 fix:[['Bei Rechnungen und Unklarem fragt er erst. Falsch einsortiert: zurückholen, er lernt daraus.','With invoices and unclear mails it asks first. Wrongly sorted: undo it, it learns from that.']]},
{id:'documents',grp:'data',sw:'chat.documents',me:'docbox',ng:1,t:['Eigene Dokumente','Own documents'],
 what:[['Du lädst Dokumente hoch, der Assistent sucht darin, wenn eine Frage dazu passt. Kein anderes Profil sieht sie.','You upload documents, the assistant searches them when a question fits. No other profile sees them.']],
 need:[['PDF, Word, Text, Markdown, HTML oder CSV, je bis 20 MB.','PDF, Word, text, Markdown, HTML or CSV, up to 20 MB each.']],
 setup:[['Admin: Funktionen → Eigene Dokumente an.','Admin: Features → Own documents on.'],['Profil: Ich → Dokumente → „Dokument hinzufügen“.','Profile: Me → Documents → "Add document".']],
 say:[['„Was steht in meinem Mietvertrag zur Kündigungsfrist?“','"What does my lease say about the notice period?"']],
 out:NOTHING_OUT,
 off:[['Ich → Dokumente → „Löschen“.','Me → Documents → "Delete".']],
 fix:[['Findet nichts: gescannte PDFs ohne Text kann er nicht lesen.','Finds nothing: scanned PDFs without text cannot be read.']]},
{id:'parcels',grp:'post',sw:'chat.parcels',me:'parbox',ng:1,ro:1,t:['Pakete','Parcels'],
 what:[['Aus den Versandmails von DHL, Hermes, DPD, GLS, UPS und Amazon der letzten 14 Tage: was heute kommt, was unterwegs ist, was zur Abholung liegt und was zugestellt wurde.','From the shipping mails of DHL, Hermes, DPD, GLS, UPS and Amazon of the last 14 days: what comes today, what is on its way, what waits for pick-up and what was delivered.']],
 need:[['Ein verbundenes Postfach (siehe „E-Mail lesen“).','A connected mailbox (see "Reading e-mail").']],
 setup:[['Admin: Funktionen → E-Mail lesen und Pakete an.','Admin: Features → Reading e-mail and Parcels on.'],['Profil: Ich → Pakete → „Pakete für mich erkennen“ an.','Profile: Me → Parcels → switch on "Recognise parcels for me".'],['Wer eine Meldung will: Ich → Von selbst → „Paket kommt heute“.','For a notice: Me → Proactive → "Parcel comes today".']],
 say:[['„Kommt heute ein Paket?“','"Is a parcel coming today?"'],['„Wo ist meine Zalando-Bestellung?“','"Where is my Zalando order?"']],
 out:[['Nichts. Keine Paketfirma wird gefragt.','Nothing. No carrier is asked.']],
 off:[['Schalter aus. Es wird nichts gespeichert außer einer kurzen Zwischenablage im Arbeitsspeicher.','Switch off. Nothing is stored except a short cache in memory.']],
 fix:[['Ein Paket fehlt: Kam die Versandmail an ein verbundenes Postfach? Mails von Shops ohne Paketfirma im Absender erkennt er nicht.','A parcel is missing: did the shipping mail go to a connected mailbox? Mails from shops without the carrier as sender are not recognised.']]},
// ------------------------------------------------------------------ Zuhause
{id:'ha',grp:'home',sw:'chat.homeassistant',me:'habox',ng:1,t:['Home Assistant','Home Assistant'],
 what:[['Licht, Geräte und Heizung per Sprache steuern und Werte abfragen. Nach jedem Schalten liest der Spark den echten Zustand nach und sagt nur, was wirklich passiert ist.','Control lights, devices and heating by voice and ask for values. After switching, the Spark reads back the real state and reports only what really happened.']],
 need:[['Dein Home Assistant und einen langlebigen Zugriffstoken, am besten von einem eigenen Benutzer ohne Admin-Rechte.','Your Home Assistant and a long-lived access token, ideally from a separate user without admin rights.']],
 setup:[['Admin: Funktionen → Home Assistant an.','Admin: Features → Home Assistant on.'],['In Home Assistant: dein Profil → Sicherheit → Langlebige Zugriffstoken → Token erstellen.','In Home Assistant: your profile → Security → Long-lived access tokens → Create token.'],['Profil: Ich → Smart Home: Adresse und Token, „Prüfen und speichern“.','Profile: Me → Smart home: address and token, "Check and save".'],['Empfohlen: ein Codewort für Änderungen setzen.','Recommended: set a code word for changes.']],
 say:[['„Wie warm ist es im Bad?“','"How warm is the bathroom?"'],['„Mach das Licht im Wohnzimmer an, Codewort Sonnenblume.“','"Turn on the living room light, code word sunflower."'],['„Was steht auf der Einkaufsliste?“','"What is on the shopping list?"']],
 out:[['Der Spark spricht direkt mit deinem Home Assistant. Sonst nichts.','The Spark talks directly to your Home Assistant. Nothing else.']],
 off:[['Ich → Smart Home → „Trennen“.','Me → Smart home → "Disconnect".']],
 fix:[['Gerät nicht gefunden: den Namen sagen, den es in Home Assistant hat.','Device not found: say the name it has in Home Assistant.'],['Schaltet nicht: Codewort in derselben Nachricht sagen. Schlösser, Alarmanlagen und Updates schaltet er nie.','Does not switch: say the code word in the same message. Locks, alarms and updates are never switched.']]},
// ------------------------------------------------------------------ Unterwegs und Geräte
{id:'push',grp:'day',me:'notebox',t:['Mitteilungen aufs Handy','Notifications to your phone'],
 what:[['Erinnerungen, das Tagesbriefing und „Von selbst melden“ kommen als Mitteilung, auch wenn die Seite zu ist.','Reminders, the daily briefing and proactive notices arrive as notifications, even with the page closed.']],
 need:[['Die Seite über https mit echtem Zertifikat (dein Reverse Proxy). Auf dem iPhone: die Seite als App auf dem Home-Bildschirm.','The page over https with a real certificate (your reverse proxy). On iPhone: the page as an app on the home screen.']],
 setup:[['iPhone: Seite in Safari öffnen, „Teilen → Zum Home-Bildschirm“, dann die App von dort öffnen.','iPhone: open the page in Safari, "Share → Add to Home Screen", then open the app from there.'],['Ich → Mitteilungen → „Einschalten“ und erlauben.','Me → Notifications → "Switch on" and allow.']],
 say:[['Nichts zu sagen, sie kommen von selbst.','Nothing to say, they come by themselves.']],
 out:[['Die Mitteilung geht verschlüsselt über den Push-Dienst deines Browsers (bei Apple über Apple).','The notification goes encrypted through your browser\'s push service (Apple\'s for Apple devices).']],
 off:[['Ich → Mitteilungen → „Ausschalten“.','Me → Notifications → "Switch off".']],
 fix:[['Knopf fehlt: Seite nicht über https oder auf dem iPhone nicht als App geöffnet.','Button missing: page not over https, or on iPhone not opened as an app.']]},
{id:'telegram',grp:'go',sw:'chat.telegram',me:'tgbox',ng:1,t:['Telegram','Telegram'],
 what:[['Du schreibst dem Assistenten über einen eigenen Telegram-Bot oder schickst eine Sprachnachricht, von überall. Der Spark fragt Telegram selbst nach neuen Nachrichten, es braucht keinen offenen Port. Auf Wunsch kommen Erinnerungen und Hinweise auch dort an.','You write to the assistant through your own Telegram bot or send a voice message, from anywhere. The Spark asks Telegram for new messages itself, no open port is needed. If you like, reminders and notes arrive there too.']],
 need:[['Die Telegram-App und einen Bot, den der Admin einmal bei @BotFather anlegt.','The Telegram app and a bot the admin creates once with @BotFather.']],
 setup:[['Bot anlegen: In Telegram @BotFather öffnen und /newbot schicken.','Create the bot: open @BotFather in Telegram and send /newbot.'],['Einen Namen eingeben (z. B. „Spark“), dann einen Benutzernamen, der auf „bot“ endet (z. B. „meinspark_bot“).','Enter a name (e.g. "Spark"), then a user name ending in "bot" (e.g. "myspark_bot").'],['BotFather schickt den Token (Zahl:Buchstaben). Kopieren und niemandem zeigen.','BotFather sends the token (number:letters). Copy it and show it to nobody.'],['Empfohlen: /setjoingroups → deinen Bot → Disable, dann kann ihn niemand in Gruppen holen.','Recommended: /setjoingroups → your bot → Disable, so nobody can add it to groups.'],['Admin: Funktionen → Telegram an, Token einfügen, „Prüfen und speichern“, dann unten „Speichern“.','Admin: Features → Telegram on, paste the token, "Check and save", then "Save" at the bottom.'],['Profil: Ich → Telegram → „Mit Telegram verbinden“, den Link öffnen und im Bot „Starten“ tippen.','Profile: Me → Telegram → "Link with Telegram", open the link and tap "Start" in the bot.'],['Dann pro Profil wählen: Sprachantworten, Mitteilungen, Persönliches (Kalender, Mail …), Smart Home mit Codewort. Alles ist zuerst aus.','Then choose per profile: voice answers, notifications, personal data (calendar, mail …), smart home with code word. Everything starts off.']],
 say:[['Einfach schreiben oder eine Sprachnachricht schicken, z. B. „Wie wird das Wetter morgen?“','Just write or send a voice message, e.g. "What is the weather tomorrow?"'],['/neu beginnt ein neues Gespräch, /stimme schaltet Sprachantworten um, /trennen löst die Verbindung.','/neu starts a new conversation, /stimme toggles voice answers, /trennen unlinks.'],['Smart Home (wenn erlaubt): „Codewort, mach das Licht im Flur an.“','Smart home (if allowed): "Code word, turn on the hall light."']],
 out:[['Deine Nachrichten und die Antworten laufen über die Server von Telegram. Deshalb sind Kalender, Mail, Kontakte, Pakete und Dokumente dort aus, bis du sie erlaubst.','Your messages and the answers pass Telegram\'s servers. That is why calendar, mail, contacts, parcels and documents stay off there until you allow them.']],
 off:[['Profil: „Trennen“ oder /trennen im Bot. Admin: „Token löschen“ oder Telegram aus; bei @BotFather mit /deletebot ganz löschen.','Profile: "Unlink" or /trennen in the bot. Admin: "Delete token" or Telegram off; delete it for good with /deletebot at @BotFather.']],
 fix:[['Bot antwortet nicht: Ist Telegram unter Funktionen an und gespeichert? Der Spark braucht Internet zu api.telegram.org.','Bot does not answer: is Telegram on under Features and saved? The Spark needs internet access to api.telegram.org.'],['„Dieser Spark-Assistent ist privat“: Das Konto ist noch nicht verbunden, im Panel einen neuen Code holen.','"This Spark assistant is private": the account is not linked yet; get a new code in the panel.'],['Kein Zugriff auf Termine: Ich → Telegram → „Persönliches über Telegram erlauben“.','No access to appointments: Me → Telegram → "Allow personal data over Telegram".']]},
{id:'esp32',grp:'home',sw:'chat.esp32',me:'espbox',ng:1,t:['Eigene Lautsprecher (ESP32)','Own speakers (ESP32)'],
 what:[['Ein kleines ESP32-S3-Board mit Mikrofon und Lautsprecher wird zum Sprachassistenten im Raum. Es hört auf „Jarvis“ oder den Knopf, fragt deinen Spark und antwortet in deiner Stimme, mit Gedächtnis, Kalender und Smart Home (mit Codewort). Es spricht nur mit deinem Spark, mit keiner Cloud.','A small ESP32-S3 board with a microphone and speaker becomes a voice assistant in the room. It listens for "Jarvis" or the button, asks your Spark and answers in your voice, with memory, calendar and smart home (with code word). It talks only to your Spark, never to a cloud.']],
 need:[['Ein ESP32-S3-Board mit 16 MB Flash und PSRAM, Mikrofon INMP441 und Verstärker MAX98357A (z. B. die „XiaoZhi“-Steckbrett-Boards, auch von diymore), ein USB-Datenkabel und Chrome oder Edge am PC oder Mac.','An ESP32-S3 board with 16 MB flash and PSRAM, INMP441 microphone and MAX98357A amplifier (e.g. the "XiaoZhi" breadboard boards, also from diymore), a USB data cable and Chrome or Edge on a PC or Mac.'],['Den Spark unter einer Adresse, die das Board erreicht: am besten dein Reverse Proxy mit echtem Zertifikat (WebSockets erlaubt), im Heimnetz geht auch http://<Spark-IP>:31080.','The Spark at an address the board reaches: best your reverse proxy with a real certificate (WebSockets allowed); at home http://<Spark IP>:31080 works too.']],
 setup:[['Admin: Funktionen → Eigene Lautsprecher an, speichern, dann „Firmware jetzt holen“. Die Adresse für die Lautsprecher eintragen, wenn das Panel sonst unter einer anderen geöffnet wird.','Admin: Features → Own speakers on, save, then "Fetch firmware now". Enter the address for the speakers if the panel is usually opened under another one.'],['Profil: Ich → Lautsprecher → „Eigene Lautsprecher für mich“ an.','Profile: Me → Speakers → "Own speakers for me" on.'],['Board per USB an den PC, unter „Lautsprecher hinzufügen“ „Neues Board per USB einrichten“: Name, Board, WLAN eingeben, „Board verbinden und einrichten“, im Fenster des Browsers den USB-Anschluss wählen.','Board to the PC over USB, under "Add a speaker" "Set up a new board over USB": enter name, board and Wi-Fi, "Connect board and set up", pick the USB port in the browser\'s window.'],['Nach etwa einer Minute startet das Board neu und steht als „verbunden“ in der Liste, sobald du es ansprichst. Antippen öffnet seine Seite mit Klang, Raum-Modus, Stimme, Firmware und Prüfen.','After about a minute the board restarts and shows as "connected" in the list once you talk to it. Tapping it opens its page with sound, room mode, voice, firmware and check.'],['Ohne PC: Ein Board mit Spark-Firmware zeigt oder sagt beim Start einen 6-stelligen Code, den du unter „Lautsprecher hinzufügen“ → „Board zeigt einen Code“ eingibst.','Without a PC: a board with the Spark firmware shows or says a 6-digit code at start, which you enter under "Add a speaker" → "Board shows a code".']],
 say:[['„Jarvis“ (oder Knopf drücken), dann: „Wie wird das Wetter morgen?“','"Jarvis" (or press the button), then: "What is the weather tomorrow?"'],['Während er spricht, Knopf drücken oder „Jarvis“ sagen unterbricht ihn.','Pressing the button or saying "Jarvis" while it speaks interrupts it.']],
 out:[['Nichts. Ton und Text bleiben zwischen Board und Spark. Nur die Firmware holt der Spark einmal am Tag aus deinem GitHub-Repo; das WLAN-Passwort bekommt nur das Board, nie der Spark.','Nothing. Sound and text stay between board and Spark. Only the firmware is fetched by the Spark once a day from your GitHub repo; only the board gets the Wi-Fi password, never the Spark.']],
 off:[['Ich → Lautsprecher → Lautsprecher antippen → „Lautsprecher entfernen“: Der Schlüssel gilt sofort nicht mehr. Der eigene Schalter aus sperrt alle deine Lautsprecher, der Admin-Schalter alle im Haus.','Me → Speakers → tap the speaker → "Remove speaker": the key stops working at once. Your own switch off locks all your speakers, the admin switch all in the house.'],['Updates kommen beim Start des Boards von selbst; „Updates von selbst“ aus, dann nur über „Jetzt aktualisieren“.','Updates come by themselves when the board starts; "Updates by themselves" off, then only with "Update now".']],
 fix:[['Kein USB-Fenster oder kein Anschluss: Datenkabel nehmen, Chrome oder Edge am PC (nicht iPhone), Seite über https.','No USB window or no port: use a data cable, Chrome or Edge on a PC (not iPhone), page over https.'],['Verbinden klappt nicht: BOOT gedrückt halten, kurz RESET drücken, BOOT loslassen, nochmal versuchen.','Connecting fails: hold BOOT, press RESET briefly, release BOOT, try again.'],['Board zeigt einen Server-Fehler: Adresse prüfen (selbst signiertes Zertifikat geht nicht), der Reverse Proxy muss WebSockets durchlassen, das Profil muss „Eigene Lautsprecher für mich“ an haben.','Board shows a server error: check the address (a self-signed certificate does not work), the reverse proxy must let WebSockets through, the profile must have "Own speakers for me" on.'],['Findet das WLAN nicht: Nur 2,4 GHz. Das Board öffnet dann ein eigenes WLAN zur Eingabe; oder per USB neu einrichten.','Does not find the Wi-Fi: 2.4 GHz only. The board then opens its own Wi-Fi for entering it; or set it up again over USB.']]},
{id:'iphone',grp:'go',sw:'chat.iphone',me:'appbox',ng:1,t:['iPhone-App „Spark“','iPhone app "Spark"'],
 what:[['Eine eigene App fürs iPhone: Knopf drücken, fragen, die Antwort kommt mit der Spark-Stimme, auch bei gesperrtem Bildschirm. „Hey Siri, Frag Spark“ geht auch über die App, ohne Kurzbefehl.','An own app for the iPhone: press the button, ask, the answer comes in the Spark voice, also with the screen locked. "Hey Siri, Ask Spark" works through the app too, without a shortcut.']],
 need:[['Ein Mac mit Xcode und ein iPhone mit iOS 17 oder neuer. Die App baust du selbst aus dem Ordner ios/ im Repo (Anleitung in docs/de/iphone-app.md).','A Mac with Xcode and an iPhone with iOS 17 or later. You build the app yourself from the ios/ folder in the repo (guide in docs/en/iphone-app.md).'],['Die Seite über https mit echtem Zertifikat (dein Reverse Proxy).','The page over https with a real certificate (your reverse proxy).']],
 setup:[['Admin: Funktionen → iPhone-App an.','Admin: Features → iPhone app on.'],['Profil: Ich → iPhone-App → „iPhone-App für mich“ an.','Profile: Me → iPhone app → switch on "iPhone app for me".'],['„iPhone koppeln“: auf dem iPhone den Link antippen, am PC den QR-Code mit der Kamera des iPhones scannen. Die App öffnet sich und ist gekoppelt.','"Pair an iPhone": on the iPhone tap the link, on a PC scan the QR code with the iPhone camera. The app opens and is paired.']],
 say:[['In der App: Knopf drücken, sprechen, nochmal drücken.','In the app: press the button, speak, press again.'],['„Hey Siri, Frag Spark“, dann die Frage.','"Hey Siri, Ask Spark", then the question.']],
 out:[['Nichts. Ton und Text gehen direkt zwischen iPhone und Spark. Nur „Hey Siri“ macht Siri bei Apple zu Text.','Nothing. Sound and text go directly between iPhone and Spark. Only "Hey Siri" is turned into text by Siri at Apple.']],
 off:[['Ich → iPhone-App → iPhone „Entfernen“: Sein Schlüssel gilt sofort nicht mehr. Der eigene Schalter aus sperrt alle deine iPhones, der Admin-Schalter alle.','Me → iPhone app → "Remove" the iPhone: its key stops working at once. Your own switch off locks all your iPhones, the admin switch all of them.']],
 fix:[['App sagt „Kopplung abgelaufen“: Der Link gilt 10 Minuten und nur einmal, einen neuen holen.','App says "pairing expired": the link is valid for 10 minutes and once, get a new one.'],['Licht schaltet nicht aus der App: Ich → iPhone-App → „Smart Home aus der App“ an, Codewort sagen.','Light does not switch from the app: Me → iPhone app → "Smart home from the app" on, say the code word.']]},
{id:'iphonepush',grp:'go',sw:'chat.iphone_push',ng:1,t:['Push an die iPhone-App','Push to the iPhone app'],
 what:[['Erinnerungen, Morgenrunde und Hinweise von selbst kommen auf dem iPhone auch dann, wenn die App geschlossen ist. Über Apple geht nur „Neue Nachricht vom Spark“; den Text holt die App selbst vom Spark und zeigt ihn im Banner.','Reminders, the morning briefing and notes come to the iPhone even when the app is closed. Only "New message from the Spark" goes through Apple; the app fetches the text itself from the Spark and shows it in the banner.']],
 need:[['Ein Apple-Developer-Konto (99 €/Jahr) und die iPhone-App „Spark“.','An Apple developer account (99 €/year) and the iPhone app "Spark".'],['Der Spark muss api.push.apple.com erreichen.','The Spark must reach api.push.apple.com.']],
 setup:[['developer.apple.com → Certificates, IDs & Profiles → Keys → „+“, „Apple Push Notifications service (APNs)“ anhaken, die .p8-Datei herunterladen und Key ID notieren.','developer.apple.com → Certificates, IDs & Profiles → Keys → "+", tick "Apple Push Notifications service (APNs)", download the .p8 file and note the Key ID.'],['Admin: Funktionen → Push an die iPhone-App an, .p8, Key ID, Team ID und Bundle-ID eintragen, „Entwicklung“ für Xcode oder „Produktion“ für TestFlight, speichern.','Admin: Features → Push to the iPhone app on, enter .p8, Key ID, Team ID and bundle ID, "Development" for Xcode or "Production" for TestFlight, save.'],['Profil: Ich → iPhone-App → „Meldungen aufs iPhone“ an, die App einmal öffnen und Mitteilungen erlauben, dann „Test-Meldung schicken“.','Profile: Me → iPhone app → "Notifications to the iPhone" on, open the app once and allow notifications, then "Send a test message".']],
 say:[['„Erinnere mich in 10 Minuten an den Tee“, dann die App schließen.','"Remind me about the tea in 10 minutes", then close the app.']],
 out:[['An Apple geht nur der feste Satz „Neue Nachricht vom Spark“, eine Zufallsnummer und die Push-Adresse des iPhones. Der Text bleibt 24 Stunden auf dem Spark und geht nur an die App mit ihrem Schlüssel.','Only the fixed sentence "New message from the Spark", a random number and the iPhone\'s push address go to Apple. The text stays on the Spark for 24 hours and only goes to the app with its key.']],
 off:[['Ich → iPhone-App → „Meldungen aufs iPhone“ aus. Admin: Schalter aus oder „Schlüssel löschen“. Ein entferntes iPhone bekommt sofort nichts mehr.','Me → iPhone app → "Notifications to the iPhone" off. Admin: switch off or "Delete key". A removed iPhone gets nothing any more at once.']],
 fix:[['Test sagt BadDeviceToken: Entwicklung und Produktion vertauscht.','Test says BadDeviceToken: development and production mixed up.'],['InvalidProviderToken: Key ID oder Team ID passen nicht zum Schlüssel.','InvalidProviderToken: Key ID or Team ID do not match the key.'],['Banner zeigt nur „Neue Nachricht“: Der Spark war nicht erreichbar oder die Nachricht ist älter als 24 Stunden.','Banner only shows "New message": the Spark could not be reached or the message is older than 24 hours.']]},
{id:'siri',grp:'go',t:['„Hey Siri, frag Spark“','"Hey Siri, ask Spark"'],
 what:[['Ein iPhone-Kurzbefehl schickt deine Frage an den Spark, Siri liest die Antwort vor. Auch auf der Apple Watch, mit AirPods und im Auto.','An iPhone shortcut sends your question to the Spark, Siri reads the answer. Also on Apple Watch, with AirPods and in the car.']],
 need:[['Ein Geräteschlüssel deines Profils und ein iPhone mit der App Kurzbefehle.','A device key of your profile and an iPhone with the Shortcuts app.']],
 setup:[['Profile: beim eigenen Profil ein Gerät „iPhone Siri“ anlegen, Schlüssel kopieren.','Profiles: add a device "iPhone Siri" to your profile, copy the key.'],['Den Kurzbefehl wie in der Karte „Hey Siri, frag Spark“ unter Einbinden beschrieben anlegen.','Build the shortcut as described in the "Hey Siri, ask Spark" card under Integrate.']],
 say:[['„Hey Siri, Frag Spark“, dann die Frage.','"Hey Siri, Ask Spark", then the question.']],
 out:[['Siri macht aus deiner Sprache Text (bei Apple). Die Frage selbst geht direkt an den Spark.','Siri turns your speech into text (at Apple). The question itself goes directly to the Spark.']],
 off:[['Gerät unter Profile löschen.','Delete the device under Profiles.']],
 fix:[['Unterwegs keine Antwort: im Kurzbefehl die Adresse deines Reverse Proxys statt der Heimnetz-Adresse.','No answer away from home: use your reverse proxy address in the shortcut, not the home address.']]},
{id:'pebble',grp:'go',t:['Pebble-Uhr','Pebble watch'],
 what:[['App „Spark“ für die Pebble: Frage per Knopfdruck, Antwort als Text und über den Lautsprecher der Uhr.','"Spark" app for the Pebble: ask with a button, answer as text and through the watch speaker.']],
 need:[['Pebble Time 2, Core 2 Duo oder Round 2, ein Geräteschlüssel deines Profils.','Pebble Time 2, Core 2 Duo or Round 2, a device key of your profile.']],
 setup:[['Profile: Gerät „Pebble“ anlegen, Schlüssel kopieren.','Profiles: add a device "Pebble", copy the key.'],['Die App-Datei aus der Karte „Pebble-Uhr“ unter Einbinden mit der Pebble-App öffnen.','Open the app file from the "Pebble watch" card under Integrate with the Pebble app.'],['In der Pebble-App bei „Spark“ Adresse und Schlüssel eintragen.','In the Pebble app enter address and key for "Spark".']],
 say:[['SELECT fragt, nochmal SELECT stoppt, lang SELECT beginnt ein neues Gespräch.','SELECT asks, SELECT again stops, long SELECT starts a new conversation.']],
 out:[['Das Diktieren macht die Pebble-App auf dem Handy, je nach Einstellung dort auch über einen Online-Dienst.','Dictation is done by the Pebble phone app, depending on its setting also through an online service.']],
 off:[['Gerät unter Profile löschen.','Delete the device under Profiles.']],
 fix:[['Leise: Uhr → Einstellungen → Töne → Lautstärke.','Quiet: watch → Settings → Sounds → Volume.'],['Unterwegs: das Handy muss den Spark erreichen (VPN oder Proxy).','Away from home: the phone has to reach the Spark (VPN or proxy).']]},
{id:'apps',grp:'go',t:['Open WebUI und eigene Programme','Open WebUI and own programs'],
 what:[['Spracherkennung und Sprachausgabe sprechen die OpenAI-Audio-API. Jede App mit eigener „Base URL“ kann sie nutzen.','Speech recognition and speech output speak the OpenAI audio API. Any app with its own "Base URL" can use them.']],
 need:[['Die Adressen und, falls gesetzt, den API-Schlüssel (Einstellungen → Sicherheit).','The addresses and, if set, the API key (Settings → Security).']],
 setup:[['Adressen und Beispiele stehen unter Einbinden (Open WebUI, Andere Apps, curl, Python).','Addresses and examples are under Integrate (Open WebUI, Other apps, curl, Python).']],
 say:[['Je nach App.','Depends on the app.']],
 out:NOTHING_OUT,
 off:[['API-Schlüssel ändern sperrt alle Apps mit dem alten Schlüssel aus.','Changing the API key locks out all apps using the old key.']],
 fix:[['Unter Zustand → Prüfen beide Dienste direkt ausprobieren.','Try both services directly under Status → Checks.']]},
// ------------------------------------------------------------------ Sicherheit und Zugang
{id:'mfa',grp:'sec',sw:'chat.mfa',me:'secbox',t:['Zweiter Anmeldeschritt','Second sign-in step'],
 what:[['Zur Anmeldung mit Name und PIN kommt ein Code aus einer Authenticator-App. Geräte mit Schlüssel brauchen keinen Code.','Signing in with name and PIN also needs a code from an authenticator app. Devices with a key need no code.']],
 need:[['Eine Authenticator-App (z. B. Apple Passwörter, Google Authenticator, 2FAS).','An authenticator app (e.g. Apple Passwords, Google Authenticator, 2FAS).']],
 setup:[['Admin: Funktionen → Zweiter Anmeldeschritt an. Für das Admin-Passwort: Einstellungen → Sicherheit.','Admin: Features → Second sign-in step on. For the admin password: Settings → Security.'],['Profil: Ich → Sicherheit → QR-Code scannen, Code eingeben, Wiederherstellungscodes aufbewahren.','Profile: Me → Security → scan the QR code, enter a code, keep the recovery codes.']],
 say:[['Bei der Anmeldung den 6-stelligen Code eingeben. „Diesem Browser 30 Tage vertrauen“ spart das Eintippen.','Enter the 6-digit code when signing in. "Trust this browser for 30 days" saves typing.']],
 out:NOTHING_OUT,
 off:[['Ich → Sicherheit → ausschalten (braucht einen Code). Der Admin kann ihn für ein Profil zurücksetzen.','Me → Security → switch off (needs a code). The admin can reset it for a profile.']],
 fix:[['Handy weg: einen Wiederherstellungscode statt des Codes eingeben.','Phone gone: enter a recovery code instead of the code.']]},
{id:'public',grp:'sec',sw:'chat.public',t:['Assistent ohne Passwort','Assistant without password'],
 what:[['An: Die Startseite ist für alle im Netz offen, auch für Gäste. Aus: nur angemeldete Profile und Geräte mit Schlüssel.','On: the start page is open to everyone on the network, guests included. Off: only signed-in profiles and devices with a key.']],
 need:[['Nichts.','Nothing.']],
 setup:[['Admin: Einstellungen → Sicherheit → Zugang zum Assistenten.','Admin: Settings → Security → Access to the assistant.']],
 say:[['Gäste können fragen, bekommen aber nie persönliche Daten, Smart Home oder Einstellungen.','Guests can ask but never get personal data, smart home or settings.']],
 out:NOTHING_OUT,
 off:[['Schalter aus. Einstellungen sind immer geschützt.','Switch off. Settings are always protected.']],
 fix:[['Ist der Spark über deinen Reverse Proxy aus dem Internet erreichbar, lieber aus lassen.','If the Spark is reachable from the internet via your reverse proxy, better keep it off.']]},
{id:'lan',grp:'sec',sw:'panel.allow_lan',t:['Heimnetz-Adressen','Home network addresses'],
 what:[['Erlaubt, dass Kalender, Adressbücher, Aufgaben und Postfächer der Profile auf einem Server im Heimnetz liegen, z. B. auf einem NAS.','Allows profile calendars, address books, task lists and mailboxes on a server in the home network, e.g. a NAS.']],
 need:[['Einen Kalender-, Kontakt- oder Mailserver im Heimnetz.','A calendar, contacts or mail server in the home network.']],
 setup:[['Admin: Einstellungen → Sicherheit → Heimnetz-Adressen erlauben.','Admin: Settings → Security → Allow home network addresses.']],
 say:[['Nichts zu sagen.','Nothing to say.']],
 out:NOTHING_OUT,
 off:[['Haken entfernen. Dann gehen nur Adressen im Internet (iCloud, GMX und Co.).','Untick it. Then only internet addresses work (iCloud, GMX and so on).']],
 fix:[['„addresses in the home network are off“: diesen Haken setzen. Home Assistant braucht ihn nicht.','"addresses in the home network are off": tick this box. Home Assistant does not need it.']]},
{id:'proxies',grp:'sec',sw:'panel.trusted_proxies',t:['Reverse Proxy','Reverse proxy'],
 what:[['Sagt dem Spark, welchem Gerät er die echte Absender-Adresse glauben darf. Dann greift die Sperre nach falschen Passwörtern pro Absender.','Tells the Spark which device it may believe about the real sender address. Then the lock after wrong passwords works per sender.']],
 need:[['Die Adresse deines Reverse Proxys im Heimnetz.','The address of your reverse proxy on the home network.']],
 setup:[['Admin: Einstellungen → Sicherheit → Adressen des Reverse-Proxys, z. B. 192.168.1.10.','Admin: Settings → Security → Reverse proxy addresses, e.g. 192.168.1.10.']],
 say:[['Nichts zu sagen.','Nothing to say.']],
 out:NOTHING_OUT,
 off:[['Feld leeren.','Clear the field.']],
 fix:[['Danach kein Zugriff über den Proxy: Adresse prüfen, die der Proxy im Heimnetz hat (nicht die öffentliche).','No access through the proxy afterwards: check the proxy\'s home network address (not the public one).']]},
];
// ---------------------------------------------------------------- rendering
const gT=p=>Array.isArray(p)?t(p[0],p[1]):p;
const guideOf=id=>GUIDES.find(g=>g.id===id);
function guideHTML(g){return GSECT.filter(([k])=>g[k]&&g[k].length).map(([k,de,en])=>{
    const items=g[k].map(x=>`<li>${esc(gT(x))}</li>`).join('');
    return `<div class="gsec"><b>${esc(t(de,en))}</b>${k==='setup'?`<ol>${items}</ol>`:g[k].length>1?`<ul>${items}</ul>`:`<p>${esc(gT(g[k][0]))}</p>`}</div>`}).join('')}
function guideBox(g,open,plain){const d=document.createElement('details');d.className='guide';d.dataset.guide=g.id;d.open=!!open;
  d.innerHTML=`<summary>${plain?'':esc(t('Anleitung','Guide'))+': '}${esc(gT(g.t))}</summary><div class="gbody">${guideHTML(g)}</div>`;return d}
// Einstellungen → Funktionen: rows sorted into the groups, each feature one short line (name, mark, switch).
// A tap on the name opens its sentence, marks, guide and settings below; switching it on opens it too.
function guidesFeat(){const pane=$('pane-feat');if(!pane||pane.dataset.grouped)return;pane.dataset.grouped='1';
  GGROUPS.forEach(([gid,de,en])=>{const rows=GUIDES.filter(g=>g.grp===gid&&g.sw).map(g=>{const el=$(g.sw);return el&&pane.contains(el)?[g,el.closest('.setrow')]:null}).filter(Boolean);
    if(!rows.length)return;
    const box=document.createElement('details');box.className='fgrp';box.open=true;box.dataset.grp=gid;
    box.innerHTML=`<summary><b>${esc(t(de,en))}</b><span class="fcount"></span></summary>`;
    const bar=pane.querySelector(':scope>.savebar');bar?pane.insertBefore(box,bar):pane.appendChild(box);
    // each switch takes its settings along: every block on the page with data-show="<its id>" goes right
    // below it (indented there, only shown while the switch is on), wherever it stands in the HTML
    // a switch that only shows while another one is on (Pakete under E-Mail) comes along with that one
    const take=(sw,to)=>pane.querySelectorAll(`:scope>[data-show="${sw}"]`).forEach(d=>{
      if(!d.classList.contains('setrow')){d.classList.add('fdetail');to.appendChild(d);return}
      to.appendChild(d);const inner=d.querySelector('.tgl input[id]');if(inner)take(inner.id,to)});
    rows.forEach(([g,row])=>{featTags(g,row);if(row.parentNode===box||row.closest('.fitem')||(row.dataset.show&&rows.some(([x])=>x.sw===row.dataset.show)))return;
      const it=document.createElement('div');it.className='fitem';it.dataset.sw=g.sw;box.appendChild(it);it.appendChild(row);take(g.sw,it);featItem(it,row)})});
  featBar(pane);guidesCount()}
function featItem(it,row){const btn=document.createElement('button');btn.type='button';btn.className='fexp';btn.setAttribute('aria-expanded','false');
  btn.setAttribute('aria-label',t('Details','Details'));row.prepend(btn);
  const nm=row.querySelector('.lbl>b');if(nm){const n=document.createElement('span');n.className='fneed';n.hidden=true;n.textContent=t('braucht dich','needs you');nm.appendChild(n)}
  btn.onclick=()=>featOpen(it,!it.classList.contains('open'));
  row.querySelector('.lbl').addEventListener('click',e=>{if(e.target.closest('button,a,input,select,textarea'))return;featOpen(it,!it.classList.contains('open'))});
  const sw=$(it.dataset.sw);if(sw)sw.addEventListener('change',()=>{if(sw.checked)featOpen(it,true)})}
function featOpen(it,on){it.classList.toggle('open',on);const b=it.querySelector('.fexp');if(b)b.setAttribute('aria-expanded',on?'true':'false')}
// an item needs you while its switch is on and a field it needs is empty ([data-req]) or a state says so ([data-need="1"])
const featNeed=it=>{const sw=$(it.dataset.sw);return !!(sw&&sw.checked&&([...it.querySelectorAll('[data-req]')].some(x=>!x.value.trim())||it.querySelector('[data-need="1"]')))};
const FFILT=[['all','Alle','All'],['on','An','On'],['off','Aus','Off'],['need','Braucht dich','Needs you']];
let featF='all';try{featF=localStorage.getItem('featfilter')||'all'}catch(e){}
function featBar(pane){const top=document.createElement('div');top.className='fbar';
  top.innerHTML=`<div class="ffilt" role="group">${FFILT.map(([k,de,en])=>`<button type="button" data-f="${k}"><span>${esc(t(de,en))}</span> <i></i></button>`).join('')}</div>`+
    `<div class="fjump">${[...pane.querySelectorAll('.fgrp')].map(b=>`<button type="button" data-g="${b.dataset.grp}">${esc(b.querySelector('summary b').textContent)}</button>`).join('')}</div>`;
  const first=pane.querySelector('.fgrp');pane.insertBefore(top,first);
  top.querySelectorAll('[data-f]').forEach(b=>b.onclick=()=>{featF=b.dataset.f;try{localStorage.setItem('featfilter',featF)}catch(e){}guidesCount()});
  top.querySelectorAll('[data-g]').forEach(b=>b.onclick=()=>{const g=pane.querySelector(`.fgrp[data-grp="${b.dataset.g}"]`);if(!g)return;
    if(g.hidden){featF='all';guidesCount()}g.open=true;g.scrollIntoView({block:'start',behavior:'smooth'})})}
// a search hit inside a closed or filtered-out item: show and open it
function featShow(el){const it=el&&el.closest&&el.closest('#pane-feat .fitem');if(!it)return;if(it.hidden){featF='all';guidesCount()}featOpen(it,true)}
function guidesCount(){const pane=$('pane-feat');if(!pane)return;const items=[...pane.querySelectorAll('.fitem')];
  const st=items.map(it=>{const sw=$(it.dataset.sw),on=!!(sw&&sw.checked),need=featNeed(it);it.querySelector('.fneed').hidden=!need;return {it,on,need}});
  const n={all:st.length,on:st.filter(x=>x.on).length,off:st.filter(x=>!x.on).length,need:st.filter(x=>x.need).length};
  if(featF==='need'&&!n.need)featF='all';
  pane.querySelectorAll('.ffilt [data-f]').forEach(b=>{const k=b.dataset.f;b.querySelector('i').textContent=n[k];b.classList.toggle('on',k===featF);b.hidden=k==='need'&&!n.need;b.classList.toggle('need',k==='need')});
  st.forEach(x=>{x.it.hidden=featF==='on'?!x.on:featF==='off'?x.on:featF==='need'?!x.need:false});
  pane.querySelectorAll('.fgrp').forEach(b=>{const s=[...b.querySelectorAll('.setrow input[type=checkbox]')];
    b.hidden=![...b.querySelectorAll('.fitem')].some(x=>!x.hidden);
    const j=pane.querySelector(`.fjump [data-g="${b.dataset.grp}"]`);if(j)j.hidden=b.hidden;
    b.querySelector('.fcount').textContent=t(`${s.filter(x=>x.checked).length} von ${s.length} an`,`${s.filter(x=>x.checked).length} of ${s.length} on`)})}
document.addEventListener('change',e=>{if(e.target.closest&&e.target.closest('#pane-feat'))guidesCount()});
document.addEventListener('input',e=>{if(e.target.closest&&e.target.closest('#pane-feat [data-req]'))guidesCount()});
// small marks behind a feature's name instead of repeating it in every description
const ME_NAME={setbox:['Gespräch','Conversation'],notebox:['Mitteilungen','Notifications'],factbox:['Gedächtnis','Memory'],voicebox:['Sprechererkennung','Speaker identification'],roombox:['Raum-Modus','Room mode'],
  probox:['Von selbst','Proactive'],taskbox:['Aufgaben','Tasks'],calbox:['Kalender','Calendar'],wxbox:['Wetter','Weather'],conbox:['Kontakte','Contacts'],trbox:['Bus und Bahn','Bus and train'],
  mailbox:['E-Mail','E-mail'],parbox:['Pakete','Parcels'],docbox:['Dokumente','Documents'],habox:['Smart Home','Smart home'],tgbox:['Telegram','Telegram'],appbox:['iPhone-App','iPhone app'],espbox:['Lautsprecher','Speakers'],secbox:['Sicherheit','Security']};
function featTags(g,row){const lbl=row.querySelector('.lbl');if(!lbl||lbl.querySelector('.ftags'))return;const tags=[];
  const me=g.me||g.mep;   // mep: the profile switch sits on that page, without the guide being shown there
  if(me&&ME_NAME[me])tags.push(['me',t('einrichten unter Ich → ','set up under Me → ')+t(...ME_NAME[me])]);
  if(g.ng)tags.push(['ng',t('nie für Gäste','never for guests')]);
  if(g.ro)tags.push(['ro',t('nur lesen','read only')]);
  if(g.out&&g.out!==NOTHING_OUT)tags.push(['out',t('verlässt das Haus','leaves the house')]);
  if(!tags.length)return;const d=document.createElement('div');d.className='ftags';
  d.innerHTML=tags.map(([k,x])=>`<span class="ftag ${k}">${esc(x)}</span>`).join('');lbl.querySelector('span').after(d)}
// A small "Anleitung" button next to every admin switch that has a guide; it opens the guide below the row.
function guidesSwitches(){GUIDES.filter(g=>g.sw).forEach(g=>{const el=$(g.sw);if(!el||document.querySelector(`[data-gbtn="${g.id}"]`))return;
  const row=el.closest('.setrow'),anchor=row||(el.closest('label.chk')||el),after=row||(anchor.nextElementSibling&&anchor.nextElementSibling.classList.contains('fh')?anchor.nextElementSibling:anchor);
  const btn=document.createElement('button');btn.type='button';btn.className='gbtn';btn.dataset.gbtn=g.id;btn.textContent=t('Anleitung','Guide');
  const box=document.createElement('div');box.className='guide inline';box.hidden=true;box.innerHTML=`<div class="gbody">${guideHTML(g)}</div>`;
  btn.onclick=()=>{box.hidden=!box.hidden;btn.classList.toggle('on',!box.hidden)};
  (row?row.querySelector('.lbl'):after).appendChild(btn);after.after(box)})}
// "Ich" window: the guides of a page at its top (re-added when a page redraws itself).
function guidesMe(id){const page=$(id);if(!page)return;const list=GUIDES.filter(g=>g.me===id);
  list.slice().reverse().forEach(g=>{if(!page.querySelector(`details.guide[data-guide="${g.id}"]`))page.prepend(guideBox(g,false))})}
// Group of an "Ich" page, for the headers in its menu.
const meGroup=id=>{const g=GUIDES.find(x=>x.me===id&&x.id!=='hands');return g?g.grp:null};
// Einbinden → Anleitungen: all guides, grouped.
function guidesAll(){const el=$('guidelist');if(!el)return;
  el.innerHTML=GGROUPS.map(([gid,de,en])=>`<div class="ggrp"><h3>${esc(t(de,en))}</h3><div data-g="${gid}"></div></div>`).join('');
  GUIDES.forEach(g=>el.querySelector(`[data-g="${g.grp}"]`).appendChild(guideBox(g,false,true)))}
function guidesInit(){guidesFeat();guidesSwitches();guidesAll()}
guidesInit();
